async function exactEngraving(part,mark){
 requireLocalExactRuntime();
 if(exactNativeLocked)throw Error('Das Ende eines exakten Rechenauftrags ist noch nicht bestätigt. Weitere exakte Aufträge bleiben gesperrt.');
 const originalParts=parts,originalSources=exactPermissionSources,originalConnector=connectorPlan,originalFields=parts.map(p=>({part:p,fields:Object.entries(p)})),originalSettings=JSON.stringify(settings()),token=crypto.randomUUID();
 const {createExactModelClient}=await import('./exact-model-client.mjs');let action;
 const current=()=>!action?.cancelled&&parts===originalParts&&exactPermissionSources===originalSources&&connectorPlan===originalConnector&&JSON.stringify(settings())===originalSettings&&originalFields.every(({part,fields},i)=>parts[i]===part&&Object.keys(part).length===fields.length&&fields.every(([key,value])=>Object.is(part[key],value)))?token:'changed-'+token;
 const client=createExactModelClient({workerFactory:()=>new Worker(new URL('./exact-model-worker.mjs',import.meta.url),{type:'module'}),getCurrentProjectToken:current,onProgress:event=>{const message=event.progress?.message;if(message)$('busyText').textContent=message;}});
 action={client,cancelled:false};exactAction=action;
 try{
  const result=await client.engrave({part,settings:mark,permissionSources:exactPermissionSources,projectToken:token});
  if(current()!==token)throw Error('Projekt geändert oder Gravur abgebrochen. Das Ergebnis wird nicht übernommen.');
  const restored=await request('restoreExactProjectParts',{parts:[result.part],permissionSources:exactPermissionSources});
  if(current()!==token||restored.length!==1)throw Error('Projekt während der Gravurprüfung geändert. Das Ergebnis wird nicht übernommen.');
  return restored[0];
 }catch(error){if(client.locked||error.cancellationConfirmed===false)exactNativeLocked=true;throw error;}
 finally{try{await client.dispose();}catch{exactNativeLocked=true;}if(exactAction===action)exactAction=null;}
}
async function engraveProjectMarks(source){
 if(!source.some(p=>p.exactGeometry!==undefined))return request('engravePlanned',{parts:source,...settings()});
 const original=parts,fields=parts.map(p=>({part:p,entries:Object.entries(p)})),check=()=>{if(parts!==original||fields.some(({part,entries},i)=>parts[i]!==part||Object.keys(part).length!==entries.length||entries.some(([key,value])=>!Object.is(part[key],value))))throw Error('Projekt während der Gravurberechnung geändert. Ergebnisse verworfen.');};
 const output=[],failed=[];let engraved=0;
 for(const p of source){
  check();
  if(!p.plannedMark||p.mark){output.push(p);continue;}
  try{if(p.exactGeometry!==undefined){output.push(await exactEngraving(p,p.plannedMark));engraved++;}else{const value=await request('engravePlanned',{parts:[p],...settings()});output.push(value.parts[0]);engraved+=value.engraved;failed.push(...value.failed);}}
  catch(error){if(exactNativeLocked||['aborted','stale'].includes(error.reason)||['aborted','stale'].includes(error.workerReason)||/abgebrochen|geändert/i.test(error.message))throw error;output.push({...p,plannedMarkIssue:error.message});failed.push({id:p.id,reason:error.message});}
 }
 check();
 return {parts:output,engraved,failed};
}
