 $('supportsEnabled').checked=!!support?.enabled;const list=$('manualFinList');list.replaceChildren();
 for(const fin of support?.fins||[]){const row=document.createElement('div');row.className='double';const label=document.createElement('span');label.textContent=`Finne ${fin.id}`;const remove=document.createElement('button');remove.textContent='Entfernen';remove.setAttribute('aria-label',`Finne ${fin.id} entfernen`);remove.disabled=busy||!ready;remove.onclick=()=>task(async()=>{const current=manualFinPart(),updated=await request('removeManualFin',{data:current,supports:current.supports,finId:fin.id,...settings()});checkpoint();parts[active]={...current,supports:updated,supportNotice:updated?.warnings?.join(' ')||undefined};render();status('Manuelle Finne entfernt. Modellgeometrie bleibt erhalten.');},'Manuelle Finne entfernen …');row.append(label,remove);list.append(row);}
