$('guideHtml').onclick=()=>task(async()=>{requirePart();requireCompleteConnectorPlan(parts,connectorPlan,{required:$('connectorsRequired').checked});if(previewParts||draftPreview)throw Error('Zuerst das gewünschte Schnittergebnis übernehmen.');await new Promise(r=>setTimeout(r,30));download(assemblyHTML(parts,guideOptions()),'Montageanleitung.html','text/html');status('HTML-Anleitung erstellt. Im Browser öffnen oder farbig als PDF drucken.');},'Bebilderte HTML-Anleitung wird vorbereitet …');
function edgeOptions(){const maxCuts=Number($('maxEdgeCuts').value);if(!Number.isInteger(maxCuts)||maxCuts<1||maxCuts>32)throw Error('Maximal 1–32 Kantenschnitte wählen.');return{angle:Number($('edgeAngle').value),minPerimeter:Number($('edgeLength').value),maxCuts};}
$('findEdges').onclick=()=>task(async()=>{const o=edgeOptions();seams=await request('seams',{data:requirePart(),angle:o.angle,minPerimeter:o.minPerimeter});selectedSeam=0;const list=$('seamList');list.replaceChildren();seams.forEach((s,i)=>{const button=document.createElement('button');button.textContent=`Kontur ${i+1} · ${s.perimeter.toFixed(0)} mm`;button.classList.toggle('active',i===0);button.onclick=()=>{selectedSeam=i;list.querySelectorAll('button').forEach((b,j)=>b.classList.toggle('active',j===i));previewParts=null;render();};list.append(button);});render();status(seams.length?`${seams.length} geometrische Kantenkonturen erkannt. Gewählte Kontur orange; Schnitt in Vorschau prüfen.`:'Keine geschlossenen Kantenkonturen gefunden. Winkel reduzieren oder echte Modellgeometrie prüfen.');},'Geschlossene Kantenkonturen werden gesucht …');
