function refreshDrawControls(){
  const previous=$('drawPoint').value;const select=$('drawPoint');select.replaceChildren(new Option('Neuen Punkt hinzufügen','-1'));
  drawPoints.forEach((p,i)=>select.add(new Option(`Punkt ${i+1} · ${p.map(v=>v.toFixed(0)).join(' / ')} mm`,String(i))));
  if(Number(previous)>=0&&Number(previous)<drawPoints.length)select.value=previous;
  $('drawInfo').textContent=`${drawPoints.length} Punkte · ${drawing?'Klick setzt/ersetzt einen Punkt':'Zeichnen beendet'}. Die Kontur wird geschlossen.`;
  $('startDrawing').textContent=drawPoints.length?'Punkte weiter bearbeiten':'Neue Kontur zeichnen';
}
function drawEditableContour(){
  if(!parts.length||!drawPoints.length||draftPreview||previewParts)return;
  const group=new THREE.Group(),points=drawPoints.map(p=>new THREE.Vector3(...p));
  let linePoints=points;
  if(points.length>=3&&$('drawStyle').value==='spline')linePoints=new THREE.CatmullRomCurve3(points,true,'centripetal').getPoints(Math.max(64,points.length*16));
  else if(points.length>=3)linePoints=[...points,points[0]];
  const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(linePoints),new THREE.LineBasicMaterial({color:0xff86c9,depthTest:false}));line.renderOrder=25;group.add(line);
  const size=Math.max(...bounds(parts[active]).size)*.004;
  points.forEach((p,i)=>{const dot=new THREE.Mesh(new THREE.SphereGeometry(size,8,6),new THREE.MeshBasicMaterial({color:i===Number($('drawPoint').value)?0xffffff:0xff86c9,depthTest:false}));dot.position.copy(p);dot.renderOrder=26;group.add(dot);});
  attachOverlay(group,models.children[active]);
}
$('startDrawing').onclick=()=>{try{requirePart();pickManualFin=false;setMode('smart');drawing=true;pickMark=false;draftPreview=null;previewParts=null;$('explode').value=0;refreshDrawControls();render();status('Konturpunkte auf einer zusammenhängenden Wand setzen. Zum Drehen die Maus ziehen.');}catch(e){status(e.message,true);}};
$('stopDrawing').onclick=()=>{drawing=false;refreshDrawControls();};
$('clearDrawing').onclick=()=>{drawPoints=[];drawNormals=[];drawing=false;draftPreview=null;previewParts=null;refreshDrawControls();render();};
$('drawPoint').onchange=()=>{drawing=true;draftPreview=null;previewParts=null;refreshDrawControls();render();};
$('drawStyle').onchange=()=>{draftPreview=null;previewParts=null;render();};
$('removePoint').onclick=()=>{const chosen=Number($('drawPoint').value),i=chosen>=0?chosen:drawPoints.length-1;if(i>=0){drawPoints.splice(i,1);drawNormals.splice(i,1);}$('drawPoint').value='-1';draftPreview=null;previewParts=null;refreshDrawControls();render();};
$('adoptContour').onclick=()=>task(async()=>{
  const data=requirePart();if(!selection)throw Error('Zuerst einen Vorschlag oder eine Oberflächenregion auswählen.');
  const result=await request('adoptDrawn',{data,faces:selection.faces,depth:Number($('wallDepth').value),lineTolerance:lineTolerance()});drawPoints=result.points;drawNormals=result.normals;drawing=true;pickMark=false;draftPreview=null;previewParts=null;$('drawPoint').value='-1';refreshDrawControls();render();status('Vorschlagskontur als bearbeitbare Punkte übernommen. Vereinfachte Kontur vor dem Schneiden prüfen.');
},'Konturpunkte werden aus der Auswahl abgeleitet …');
$('previewDrawing').onclick=()=>task(async()=>{
  const data=requirePart(),depth=Number($('wallDepth').value),style=$('drawStyle').value,points=drawPoints.map(p=>[...p]),normals=drawNormals.map(p=>[...p]);
  const patch=await request('drawPreview',{data,points,normals,style,depth});
  drawing=false;draftPreview={kind:'drawn',points,normals,style,depth,cutDefinition:patch.cutDefinition,walls:patch.walls,info:'Gezeichnete geschlossene Kontur auf der Oberfläche. Erst Berechnen erzeugt Teilkörper.'};previewParts=null;refreshDrawControls();render();status('Projizierte Schnittkontur prüfen. Bei Bedarf Vorschau schließen und Punkte korrigieren.');
},'Gezeichnete Kontur wird auf die Modelloberfläche projiziert …');
