function renderPalette(){const box=$('colorPalette');box.replaceChildren();palette.forEach((color,i)=>{const label=document.createElement('label');label.textContent=`Farbe ${i+1}`;const input=document.createElement('input');input.type='color';input.value=color;input.onchange=()=>{palette[i]=input.value;status('Palette geändert. Nachbarfarben neu verteilen, um die Änderung auf Teile anzuwenden.');};label.append(input);box.append(label);});}
async function applyNeighborColors(source,preview,options={}){if(preview){const context=replacementColorContext(parts,active,source,{previewAssembly,openPreview:source===draftPreview?.surfaceParts,...options}),result=await request('neighborColors',{parts:context.parts,palette,preview:false});stageReplacementColors(source,context,result.colors);return result;}const result=await request('neighborColors',{parts:source,palette,preview:false});source.forEach((p,i)=>p.color=result.colors[i]);return result;}
$('colorNeighbors').onclick=()=>task(async()=>{requirePart();const result=await applyNeighborColors(markSource(),!!(previewParts||draftPreview));render();status(`${result.edges} Nachbarschaften geprüft. Angrenzende Teile haben unterschiedliche Farben.`);},'Kontaktflächen und Nachbarfarben werden geprüft …');
