function connectorCheck(){const required=$('connectorsRequired').checked;if(!connectorPlan)return connectorReadiness(parts,null,{required});const partIds=JSON.stringify(parts.map(part=>part?.id));if(!connectorCheckCache||connectorCheckCache.parts!==parts||connectorCheckCache.partIds!==partIds||connectorCheckCache.plan!==connectorPlan||connectorCheckCache.required!==required)connectorCheckCache={parts,partIds,plan:connectorPlan,required,value:connectorReadiness(parts,connectorPlan,{required})};return connectorCheckCache.value;}
function workflowState(){let printerValid=true;try{const {bed,margin}=settings();usableBed(bed,margin);}catch{printerValid=false;}const preview=!!(previewParts||draftPreview);return {hasModel:parts.length>0,printerValid,hasOpenPreview:preview,hasClosedParts:parts.length>0&&!preview,hasInteriorSelection:parts.some(p=>p.interiorRegion?.triangles?.length||p.exactInteriorPermission),hasExistingMarks:parts.some(p=>p.mark),requireInteriorSelection:false,busy:busy||exactReviewOpen,dirtyPrintPose:!!printPreparation?.isDirty,printPreparationOpen:!!printPreparation?.isOpen,connectorPlanPresent:!!connectorPlan||($('connectorsRequired').checked&&parts.length>1),connectorPlanPending:!connectorPlan&&$('connectorsRequired').checked&&parts.length>1,connectorIssueCount:connectorCheck().issueCount};}
function syncPresentationControls(){applicationShell?.sync();workflowUX?.sync();studioTutorial?.sync();studioHelp?.sync();if(!$('viewColorMode'))return;$('workflowPreviewMarks').hidden=!previewParts&&!draftPreview;$('viewColorMode').value=viewPresentation.mode;$('viewSingleColor').value=viewPresentation.color;$('viewSingleColor').hidden=viewPresentation.mode!=='single';$('viewColorNote').hidden=viewPresentation.mode!=='single';const check=connectorCheck();$('connectorsRequired').disabled=busy||!!connectorPlan;$('workflowExportCheck').textContent=parts.length?check.message:'';for(const id of ['export','guide','guideHtml']){$(id).disabled=busy||!parts.length||!!previewParts||!!draftPreview||!!printPreparation?.isDirty||!check.ready;$(id).title=check.ready?'':check.message;}}
