$('viewColorMode').onchange=updateViewPresentation;$('viewSingleColor').oninput=updateViewPresentation;
workflow=createGuidedWorkflow({...workflowElements,getState:workflowState,onClosePrintPreparation:()=>printPreparation.close(),onStatus:message=>status(message,true),onPhaseChange:({phase})=>{pickMark=false;pickInterior=false;pickManualFin=false;drawing=false;$('displayMode').value=phase==='print'?'print':'assembly';render();frame();document.querySelector('.left').scrollTop=0;const settingsScroll=$('appSettingsScroll');if(settingsScroll)settingsScroll.scrollTop=0;}});
