$('repairDowels').onclick=()=>task(async()=>{
 if(!connectorPlan||!connectorBaseParts)throw Error('Zuerst einen Passstiftplan laden.');
 if(previewParts||draftPreview||printPreparation?.isDirty)throw Error('Zuerst die aktuelle Vorschau übernehmen oder verwerfen.');
 const previous=connectorCheck(),base=connectorPartDecorations(connectorBaseParts,parts),options={...connectorPlan.settings,compactPairFallback:true,frontierPolicy:'fresh-contact-first-v1',maxMillis:900000};
 const result=await request('planDowels',{parts:base,...settings(),options});
 if(result.stopped)throw Error('Erneute Stiftsuche angehalten. Der bisherige Plan bleibt erhalten.');
 const plan=savedConnectorPlan(result,options),check=connectorReadiness(result.parts,plan);
 if(!check.ready&&check.issueCount>=previous.issueCount){status('Keine vollständigere Verbindungslösung gefunden. Der bisherige Plan bleibt erhalten. '+check.message,true);return;}
 checkpoint();connectorBaseParts=base;connectorPlan=plan;parts=result.parts;resetSelection();render();frame();
 status(check.ready?'Alle Stiftverbindungen und Einsteckwege vollständig geprüft.':check.message,!check.ready);
},'Alternative Stiftstellen und Montagereihenfolge prüfen …');

