studioHelp=mountStudioHelp({root:document,onOpenTutorial:topic=>studioTutorial.open(topic)});
applicationShell=mountApplicationShell({getState:()=>({hasModel:parts.length>0,busy:busy||exactReviewOpen,preview:!!(previewParts||draftPreview),previewCount:(previewParts||draftPreview?.surfaceParts)?.length}),onDemo:()=>$('demo').onclick(),onProject:()=>$('projectFile').click()});

workflowUX=mountWorkflowUX({browserOnly,getState:()=>{let capacity=null;try{const {bed,margin}=settings();capacity=usableBed(bed,margin);}catch{}return {partCount:parts.length,busy:busy||exactReviewOpen,preview:!!(previewParts||draftPreview),hasConnectorPlan:!!connectorPlan,hasInterior:parts.some(p=>p.interiorRegion?.triangles?.length||p.exactInteriorPermission),plannedMarks:parts.filter(p=>p.plannedMark&&!p.mark).length,engravedMarks:parts.filter(p=>p.mark).length,usableBed:capacity,autoMarkSize:automaticMarkSize,autoMarkDepth:automaticMarkDepth,markSettings:($('autoFitMarkSize').checked?'Automatisch eingepasst, höchstens ':'')+automaticMarkSize.toLocaleString('de-DE')+' mm hoch · '+automaticMarkDepth.toLocaleString('de-DE')+' mm tief.'};},onAutomaticMarkSettings:({size,depth})=>{automaticMarkSize=size;automaticMarkDepth=depth;showAutomaticMarkSettings();},onModelPhase:async()=>{if(await workflow.selectPhase('model')){$('interiorPanel').open=true;$('interiorPanel').scrollIntoView({block:'nearest'});}}});
